        try:
            def f(tt,*p): return gt(tt,p)
            p,_=curve_fit(f,t,dA_dt+0*t,p0=p0,maxfev=50000)
        except Exception: pass
    # joint fit with A term
    best=None
    for p0 in p0s:
        try:
            def F(X,*p):
                tt,AA=X
                return gt(tt,p[:-1]) - p[-1]*AA**1.5*tt**2
